            float p2 = MathF.Exp(s2 - mn);
            float p3 = MathF.Exp(s3 - mn);
            float p4 = MathF.Exp(s4 - mn);
            float p5 = MathF.Exp(s5 - mn);
            float p6 = MathF.Exp(s6 - mn);
            float p7 = MathF.Exp(s7 - mn);
            l = l * corr + (p0 + p1 + p2 + p3 + p4 + p5 + p6 + p7);
            o0 = o0 * corr + p0 * vs[0 + 0 + p] + p1 * vs[40 + 0 + p] + p2 * vs[80 + 0 + p] + p3 * vs[120 + 0 + p] + p4 * vs[160 + 0 + p] + p5 * vs[200 + 0 + p] + p6 * vs[240 + 0 + p] + p7 * vs[280 + 0 + p];
            o1 = o1 * corr + p0 * vs[0 + 4 + p] + p1 * vs[40 + 4 + p] + p2 * vs[80 + 4 + p] + p3 * vs[120 + 4 + p] + p4 * vs[160 + 4 + p] + p5 * vs[200 + 4 + p] + p6 * vs[240 + 4 + p] + p7 * vs[280 + 4 + p];
            o2 = o2 * corr + p0 * vs[0 + 8 + p] + p1 * vs[40 + 8 + p] + p2 * vs[80 + 8 + p] + p3 * vs[120 + 8 + p] + p4 * vs[160 + 8 + p] + p5 * vs[200 + 8 + p] + p6 * vs[240 + 8 + p] + p7 * vs[280 + 8 + p];
            o3 = o3 * corr + p0 * vs[0 + 12 + p] + p1 * vs[40 + 12 + p] + p2 * vs[80 + 12 + p] + p3 * vs[120 + 12 + p] + p4 * vs[160 + 12 + p] + p5 * vs[200 + 12 + p] + p6 * vs[240 + 12 + p] + p7 * vs[280 + 12 + p];
            o4 = o4 * corr + p0 * vs[0 + 16 + p] + p1 * vs[40 + 16 + p] + p2 * vs[80 + 16 + p] + p3 * vs[120 + 16 + p] + p4 * vs[160 + 16 + p] + p5 * vs[200 + 16 + p] + p6 * vs[240 + 16 + p] + p7 * vs[280 + 16 + p];
            o5 = o5 * corr + p0 * vs[0 + 20 + p] + p1 * vs[40 + 20 + p] + p2 * vs[80 + 20 + p] + p3 * vs[120 + 20 + p] + p4 * vs[160 + 20 + p] + p5 * vs[200 + 20 + p] + p6 * vs[240 + 20 + p] + p7 * vs[280 + 20 + p];
            o6 = o6 * corr + p0 * vs[0 + 24 + p] + p1 * vs[40 + 24 + p] + p2 * vs[80 + 24 + p] + p3 * vs[120 + 24 + p] + p4 * vs[160 + 24 + p] + p5 * vs[200 + 24 + p] + p6 * vs[240 + 24 + p] + p7 * vs[280 + 24 + p];
            o7 = o7 * corr + p0 * vs[0 + 28 + p] + p1 * vs[40 + 28 + p] + p2 * vs[80 + 28 + p] + p3 * vs[120 + 28 + p] + p4 * vs[160 + 28 + p] + p5 * vs[200 + 28 + p] + p6 * vs[240 + 28 + p] + p7 * vs[280 + 28 + p];
            o8 = o8 * corr + p0 * vs[0 + 32 + p] + p1 * vs[40 + 32 + p] + p2 * vs[80 + 32 + p] + p3 * vs[120 + 32 + p] + p4 * vs[160 + 32 + p] + p5 * vs[200 + 32 + p] + p6 * vs[240 + 32 + p] + p7 * vs[280 + 32 + p];
            o9 = o9 * corr + p0 * vs[0 + 36 + p] + p1 * vs[40 + 36 + p] + p2 * vs[80 + 36 + p] + p3 * vs[120 + 36 + p] + p4 * vs[160 + 36 + p] + p5 * vs[200 + 36 + p] + p6 * vs[240 + 36 + p] + p7 * vs[280 + 36 + p];
            Group.Barrier();
        }
        if (ok)
        {
            float inv = 1f / l;
            long ob = (long)row * H * 40 + h * 40 + p;
            O[ob + 0] = o0 * inv;
            O[ob + 4] = o1 * inv;
            O[ob + 8] = o2 * inv;
            O[ob + 12] = o3 * inv;
            O[ob + 16] = o4 * inv;
            O[ob + 20] = o5 * inv;
            O[ob + 24] = o6 * inv;
            O[ob + 28] = o7 * inv;
            O[ob + 32] = o8 * inv;
            O[ob + 36] = o9 * inv;
        }
    }

    /// <summary>D = 40, Q and K/V in one buffer. grid = ceil(Nq / 64) * H, group = 256.</summary>
    public static void SelfD40Smem(FV S, FV O, int Nq, int Nk, int H, int qStride, int qOff, int kvStride, int kOff, int vOff)
    {
        int qTile = Grid.IdxX / H, h = Grid.IdxX - qTile * H;
        int tid = Group.IdxX, p = tid & 3, ql = tid >> 2;
        int row = qTile * 64 + ql;
        bool ok = row < Nq;
        var ks = SharedMemory.Allocate<float>(320);
        var vs = SharedMemory.Allocate<float>(320);
        var red = SharedMemory.Allocate<float>(2048);   // partial dots [key][lane][query]
        long qb = (long)row * qStride + qOff + h * 40 + p;
        const float scale = 0.15811388300841897f;
        float q0 = ok ? S[qb + 0] * scale : 0f;
        float q1 = ok ? S[qb + 4] * scale : 0f;
        float q2 = ok ? S[qb + 8] * scale : 0f;
        float q3 = ok ? S[qb + 12] * scale : 0f;
        float q4 = ok ? S[qb + 16] * scale : 0f;
        float q5 = ok ? S[qb + 20] * scale : 0f;
        float q6 = ok ? S[qb + 24] * scale : 0f;
        float q7 = ok ? S[qb + 28] * scale : 0f;
        float q8 = ok ? S[qb + 32] * scale : 0f;
        float q9 = ok ? S[qb + 36] * scale : 0f;
        float o0 = 0f;
        float o1 = 0f;
        float o2 = 0f;
        float o3 = 0f;
        float o4 = 0f;
        float o5 = 0f;
        float o6 = 0f;
        float o7 = 0f;
        float o8 = 0f;
        float o9 = 0f;
        float m = -1e30f, l = 0f;
        for (int kb = 0; kb < Nk; kb += 8)
        {
            { int idx = 0 + tid; int key = idx / 40, d = idx - key * 40; int gk = kb + key;
              long kvb = (long)gk * kvStride + h * 40 + d;
              ks[idx] = gk < Nk ? S[kvb + kOff] : 0f; vs[idx] = gk < Nk ? S[kvb + vOff] : 0f; }
            if (256 + tid < 320) { int idx = 256 + tid; int key = idx / 40, d = idx - key * 40; int gk = kb + key;
              long kvb = (long)gk * kvStride + h * 40 + d;
              ks[idx] = gk < Nk ? S[kvb + kOff] : 0f; vs[idx] = gk < Nk ? S[kvb + vOff] : 0f; }
            Group.Barrier();
            float s0 = q0 * ks[0 + 0 + p] + q1 * ks[0 + 4 + p] + q2 * ks[0 + 8 + p] + q3 * ks[0 + 12 + p] + q4 * ks[0 + 16 + p] + q5 * ks[0 + 20 + p] + q6 * ks[0 + 24 + p] + q7 * ks[0 + 28 + p] + q8 * ks[0 + 32 + p] + q9 * ks[0 + 36 + p];
            red[ql + 64 * (p + 0)] = s0;
            float s1 = q0 * ks[40 + 0 + p] + q1 * ks[40 + 4 + p] + q2 * ks[40 + 8 + p] + q3 * ks[40 + 12 + p] + q4 * ks[40 + 16 + p] + q5 * ks[40 + 20 + p] + q6 * ks[40 + 24 + p] + q7 * ks[40 + 28 + p] + q8 * ks[40 + 32 + p] + q9 * ks[40 + 36 + p];
            red[ql + 64 * (p + 4)] = s1;
            float s2 = q0 * ks[80 + 0 + p] + q1 * ks[80 + 4 + p] + q2 * ks[80 + 8 + p] + q3 * ks[80 + 12 + p] + q4 * ks[80 + 16 + p] + q5 * ks[80 + 20 + p] + q6 * ks[80 + 24 + p] + q7 * ks[80 + 28 + p] + q8 * ks[80 + 32 + p] + q9 * ks[80 + 36 + p];
            red[ql + 64 * (p + 8)] = s2;
            float s3 = q0 * ks[120 + 0 + p] + q1 * ks[120 + 4 + p] + q2 * ks[120 + 8 + p] + q3 * ks[120 + 12 + p] + q4 * ks[120 + 16 + p] + q5 * ks[120 + 20 + p] + q6 * ks[120 + 24 + p] + q7 * ks[120 + 28 + p] + q8 * ks[120 + 32 + p] + q9 * ks[120 + 36 + p];
            red[ql + 64 * (p + 12)] = s3;
            float s4 = q0 * ks[160 + 0 + p] + q1 * ks[160 + 4 + p] + q2 * ks[160 + 8 + p] + q3 * ks[160 + 12 + p] + q4 * ks[160 + 16 + p] + q5 * ks[160 + 20 + p] + q6 * ks[160 + 24 + p] + q7 * ks[160 + 28 + p] + q8 * ks[160 + 32 + p] + q9 * ks[160 + 36 + p];
            red[ql + 64 * (p + 16)] = s4;
            float s5 = q0 * ks[200 + 0 + p] + q1 * ks[200 + 4 + p] + q2 * ks[200 + 8 + p] + q3 * ks[200 + 12 + p] + q4 * ks[200 + 16 + p] + q5 * ks[200 + 20 + p] + q6 * ks[200 + 24 + p] + q7 * ks[200 + 28 + p] + q8 * ks[200 + 32 + p] + q9 * ks[200 + 36 + p];
            red[ql + 64 * (p + 20)] = s5;
            float s6 = q0 * ks[240 + 0 + p] + q1 * ks[240 + 4 + p] + q2 * ks[240 + 8 + p] + q3 * ks[240 + 12 + p] + q4 * ks[240 + 16 + p] + q5 * ks[240 + 20 + p] + q6 * ks[240 + 24 + p] + q7 * ks[240 + 28 + p] + q8 * ks[240 + 32 + p] + q9 * ks[240 + 36 + p];
            red[ql + 64 * (p + 24)] = s6;
            float s7 = q0 * ks[280 + 0 + p] + q1 * ks[280 + 4 + p] + q2 * ks[280 + 8 + p] + q3 * ks[280 + 12 + p] + q4 * ks[280 + 16 + p] + q5 * ks[280 + 20 + p] + q6 * ks[280 + 24 + p] + q7 * ks[280 + 28 + p] + q8 * ks[280 + 32 + p] + q9 * ks[280 + 36 + p];
            red[ql + 64 * (p + 28)] = s7;
            Group.Barrier();
            s0 = red[ql + 0] + red[ql + 64] + red[ql + 128] + red[ql + 192];
            s1 = red[ql + 256] + red[ql + 320] + red[ql + 384] + red[ql + 448];
            s2 = red[ql + 512] + red[ql + 576] + red[ql + 640] + red[ql + 704];
            s3 = red[ql + 768] + red[ql + 832] + red[ql + 896] + red[ql + 960];
            s4 = red[ql + 1024] + red[ql + 1088] + red[ql + 1152] + red[ql + 1216];
            s5 = red[ql + 1280] + red[ql + 1344] + red[ql + 1408] + red[ql + 1472];
            s6 = red[ql + 1536] + red[ql + 1600] + red[ql + 1664] + red[ql + 1728];
            s7 = red[ql + 1792] + red[ql + 1856] + red[ql + 1920] + red[ql + 1984];
            if (kb + 0 >= Nk) s0 = -1e30f;
            if (kb + 1 >= Nk) s1 = -1e30f;
            if (kb + 2 >= Nk) s2 = -1e30f;
            if (kb + 3 >= Nk) s3 = -1e30f;
            if (kb + 4 >= Nk) s4 = -1e30f;
            if (kb + 5 >= Nk) s5 = -1e30f;
            if (kb + 6 >= Nk) s6 = -1e30f;
            if (kb + 7 >= Nk) s7 = -1e30f;
            float mn = MathF.Max(m, MathF.Max(MathF.Max(MathF.Max(MathF.Max(MathF.Max(MathF.Max(MathF.Max(s0, s1), s2), s3), s4), s5), s6), s7));
            float corr = MathF.Exp(m - mn);
            m = mn;
            float p0 = MathF.Exp(s0 - mn);
            float p1 = MathF.Exp(s1 - mn);
            float p2 = MathF.Exp(s2 - mn);
            float p3 = MathF.Exp(s3 - mn);
            float p4 = MathF.Exp(s4 - mn);
            float p5 = MathF.Exp(s5 - mn);
            float p6 = MathF.Exp(s6 - mn);
            float p7 = MathF.Exp(s7 - mn);
            l = l * corr + (p0 + p1 + p2 + p3 + p4 + p5 + p6 + p7);
            o0 = o0 * corr + p0 * vs[0 + 0 + p] + p1 * vs[40 + 0 + p] + p2 * vs[80 + 0 + p] + p3 * vs[120 + 0 + p] + p4 * vs[160 + 0 + p] + p5 * vs[200 + 0 + p] + p6 * vs[240 + 0 + p] + p7 * vs[280 + 0 + p];
            o1 = o1 * corr + p0 * vs[0 + 4 + p] + p1 * vs[40 + 4 + p] + p2 * vs[80 + 4 + p] + p3 * vs[120 + 4 + p] + p4 * vs[160 + 4 + p] + p5 * vs[200 + 4 + p] + p6 * vs[240 + 4 + p] + p7 * vs[280 + 4 + p];
            o2 = o2 * corr + p0 * vs[0 + 8 + p] + p1 * vs[40 + 8 + p] + p2 * vs[80 + 8 + p] + p3 * vs[120 + 8 + p] + p4 * vs[160 + 8 + p] + p5 * vs[200 + 8 + p] + p6 * vs[240 + 8 + p] + p7 * vs[280 + 8 + p];
            o3 = o3 * corr + p0 * vs[0 + 12 + p] + p1 * vs[40 + 12 + p] + p2 * vs[80 + 12 + p] + p3 * vs[120 + 12 + p] + p4 * vs[160 + 12 + p] + p5 * vs[200 + 12 + p] + p6 * vs[240 + 12 + p] + p7 * vs[280 + 12 + p];
            o4 = o4 * corr + p0 * vs[0 + 16 + p] + p1 * vs[40 + 16 + p] + p2 * vs[80 + 16 + p] + p3 * vs[120 + 16 + p] + p4 * vs[160 + 16 + p] + p5 * vs[200 + 16 + p] + p6 * vs[240 + 16 + p] + p7 * vs[280 + 16 + p];
            o5 = o5 * corr + p0 * vs[0 + 20 + p] + p1 * vs[40 + 20 + p] + p2 * vs[80 + 20 + p] + p3 * vs[120 + 20 + p] + p4 * vs[160 + 20 + p] + p5 * vs[200 + 20 + p] + p6 * vs[240 + 20 + p] + p7 * vs[280 + 20 + p];
            o6 = o6 * corr + p0 * vs[0 + 24 + p] + p1 * vs[40 + 24 + p] + p2 * vs[80 + 24 + p] + p3 * vs[120 + 24 + p] + p4 * vs[160 + 24 + p] + p5 * vs[200 + 24 + p] + p6 * vs[240 + 24 + p] + p7 * vs[280 + 24 + p];
            o7 = o7 * corr + p0 * vs[0 + 28 + p] + p1 * vs[40 + 28 + p] + p2 * vs[80 + 28 + p] + p3 * vs[120 + 28 + p] + p4 * vs[160 + 28 + p] + p5 * vs[200 + 28 + p] + p6 * vs[240 + 28 + p] + p7 * vs[280 + 28 + p];
            o8 = o8 * corr + p0 * vs[0 + 32 + p] + p1 * vs[40 + 32 + p] + p2 * vs[80 + 32 + p] + p3 * vs[120 + 32 + p] + p4 * vs[160 + 32 + p] + p5 * vs[200 + 32 + p] + p6 * vs[240 + 32 + p] + p7 * vs[280 + 32 + p];
            o9 = o9 * corr + p0 * vs[0 + 36 + p] + p1 * vs[40 + 36 + p] + p2 * vs[80 + 36 + p] + p3 * vs[120 + 36 + p] + p4 * vs[160 + 36 + p] + p5 * vs[200 + 36 + p] + p6 * vs[240 + 36 + p] + p7 * vs[280 + 36 + p];
            Group.Barrier();
        }
        if (ok)
        {
            float inv = 1f / l;
            long ob = (long)row * H * 40 + h * 40 + p;
            O[ob + 0] = o0 * inv;
            O[ob + 4] = o1 * inv;
            O[ob + 8] = o2 * inv;
            O[ob + 12] = o3 * inv;
            O[ob + 16] = o4 * inv;
            O[ob + 20] = o5 * inv;
            O[ob + 24] = o6 * inv;
            O[ob + 28] = o7 * inv;
            O[ob + 32] = o8 * inv;
            O[ob + 36] = o9 * inv;
        }
    }

